// Provided for lab 12.3. You do not edit this file (Metal host side).
// Encodes the exclusive scan of scan_u32.metal, the Metal counterpart of scan_u32.cu:
//
//   uint32_t scanScratchElems(uint32_t n)
//       elements of scratch the scan needs for n inputs (at least 1).
//   bool encodeExclusiveScanU32(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> in,
//                               id<MTLBuffer> out, uint32_t n, id<MTLBuffer> scratch)
//       out[0] = 0, out[i] = in[0] + ... + in[i-1]. n >= 1; in == out is allowed; the sum of all
//       inputs must fit in 32 bits; scratch holds scanScratchElems(n) elements. Encodes several
//       dispatches into enc and returns false, encoding nothing, if a scan kernel does not build
//       or cannot run 256 threads per threadgroup.
//   bool encodeCopyU32(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> in, id<MTLBuffer> out,
//                      uint32_t n)
//       out[i] = in[i]: the benchmark's reference.
//
// The dispatches go into the encoder the caller passes. An encoder made with plain
// computeCommandEncoder runs its dispatches serially, and buffers made from the device are
// hazard-tracked, so each dispatch sees the previous one's writes (notes/today/ch02-facts.md
// C9). That is what makes the levels of the scan follow one another.
//
// The pipelines are compiled from scan_u32.metal, found through the lab's shared directory.
// The course runtime compiles and caches them (pmpp/metal.h); a real application would build
// them once from a library in the same way.
#import <Metal/Metal.h>
#include <cstdint>
#include <string>

#include "pmpp/metal.h"

static const uint32_t kScanBlock = 256;   // SCAN_BLOCK_DIM in scan_u32.metal
static const uint32_t kScanTile = 1024;   // SCAN_TILE

static id<MTLComputePipelineState> scanPipeline(const char* name) {
    // PMPP_METAL_SHARED_DIR is <chapter>/shared; this lab group's provided files are in shared-g12.
    return pmpp::metal::pipeline(std::string(PMPP_METAL_SHARED_DIR) + "-g12/scan_u32.metal", name);
}

static uint32_t scanCeilDiv(uint32_t a, uint32_t b) { return (a + b - 1) / b; }

uint32_t scanScratchElems(uint32_t n) {
    uint32_t total = 0;
    while (n > kScanTile) {
        n = scanCeilDiv(n, kScanTile);
        total += (n + 3) / 4 * 4;
    }
    return total > 0 ? total : 1;
}

// One level: scan the tiles of in (at inOffset bytes) into out, scan the tile totals in place
// in scratch, add them. Offsets are in bytes and multiples of 16.
static void encodeLevel(id<MTLComputeCommandEncoder> enc, id<MTLComputePipelineState> scanTiles,
                        id<MTLComputePipelineState> addOffsets, id<MTLBuffer> in, NSUInteger inOffset,
                        id<MTLBuffer> out, NSUInteger outOffset, uint32_t n, id<MTLBuffer> scratch,
                        NSUInteger scratchOffset) {
    const uint32_t tiles = scanCeilDiv(n, kScanTile);
    const uint32_t wantTotals = tiles > 1 ? 1u : 0u;
    [enc setComputePipelineState:scanTiles];
    [enc setBuffer:in offset:inOffset atIndex:0];
    [enc setBuffer:out offset:outOffset atIndex:1];
    [enc setBuffer:scratch offset:scratchOffset atIndex:2];
    [enc setBytes:&n length:sizeof(n) atIndex:3];
    [enc setBytes:&wantTotals length:sizeof(wantTotals) atIndex:4];
    [enc dispatchThreadgroups:MTLSizeMake(tiles, 1, 1) threadsPerThreadgroup:MTLSizeMake(kScanBlock, 1, 1)];
    if (tiles == 1) {
        return;
    }
    const NSUInteger levelBytes = (NSUInteger)(tiles + 3) / 4 * 4 * sizeof(uint32_t);
    encodeLevel(enc, scanTiles, addOffsets, scratch, scratchOffset, scratch, scratchOffset, tiles, scratch,
                scratchOffset + levelBytes);
    [enc setComputePipelineState:addOffsets];
    [enc setBuffer:out offset:outOffset atIndex:0];
    [enc setBuffer:scratch offset:scratchOffset atIndex:1];
    [enc setBytes:&n length:sizeof(n) atIndex:2];
    [enc dispatchThreadgroups:MTLSizeMake(tiles, 1, 1) threadsPerThreadgroup:MTLSizeMake(kScanBlock, 1, 1)];
}

bool encodeExclusiveScanU32(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> in, id<MTLBuffer> out, uint32_t n,
                            id<MTLBuffer> scratch) {
    id<MTLComputePipelineState> scanTiles = scanPipeline("scan_tiles_u32");
    id<MTLComputePipelineState> addOffsets = scanPipeline("add_tile_offsets_u32");
    if (!scanTiles || !addOffsets || n == 0) {
        return false;
    }
    if (scanTiles.maxTotalThreadsPerThreadgroup < kScanBlock || addOffsets.maxTotalThreadsPerThreadgroup < kScanBlock) {
        return false;
    }
    encodeLevel(enc, scanTiles, addOffsets, in, 0, out, 0, n, scratch, 0);
    return true;
}

bool encodeCopyU32(id<MTLComputeCommandEncoder> enc, id<MTLBuffer> in, id<MTLBuffer> out, uint32_t n) {
    id<MTLComputePipelineState> copy = scanPipeline("copy_u32");
    if (!copy || n == 0 || copy.maxTotalThreadsPerThreadgroup < 256) {
        return false;
    }
    [enc setComputePipelineState:copy];
    [enc setBuffer:in offset:0 atIndex:0];
    [enc setBuffer:out offset:0 atIndex:1];
    [enc setBytes:&n length:sizeof(n) atIndex:2];
    [enc dispatchThreadgroups:MTLSizeMake(scanCeilDiv(n, 256), 1, 1) threadsPerThreadgroup:MTLSizeMake(256, 1, 1)];
    return true;
}
